//! What crosses between a remote control and the player it drives, plus the
//! transport verbs the app itself uses.
//!
//! The vocabulary is the web app's, one variant per player-store method that
//! `webapp/src/lib/remote/commands.js` names, and the wire names are that file's
//! op names (`play`, `play_queue`, `add`, `remove`, …) so a controller and this
//! state machine cannot drift: the same JSON drives both
//! (`tests/fixtures/commands.json` is generated by the JavaScript itself).
//!
//! Two deliberate additions, both refused by nothing on the other side:
//! `shuffle_play` (the SPA's op for `player.shufflePlay`, in the server's
//! `remote.py#OPS` too) and `seek` (sent by `controller.js#watchSeek`, the one
//! op `commandFor` never produces).

use serde::{Deserialize, Serialize};

use crate::state::Entry;

/// The server takes at most this many tracks in one command (`remote.py`).
pub const MAX_ADD: usize = 2_000;
/// …and at most this many in one queue (`commands.js#MAX_QUEUE`).
pub const MAX_QUEUE: usize = 5_000;

/// Where a queue came from: an album, a playlist, the Flow, a radio…
///
/// `kind` is the SPA's (see `lib/flow.js`: `flow`, `radio`, `album`, `playlist`,
/// `releases`, `track`), `id` names that thing and `title` is what the queue
/// panel shows. Only `flow` and `radio` are topped up when they run dry.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct Context {
    #[serde(default)]
    pub kind: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub id: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub title: Option<String>,
}

impl Context {
    pub fn new(kind: impl Into<String>) -> Self {
        Self {
            kind: kind.into(),
            id: None,
            title: None,
        }
    }

    /// Whether a queue that runs out may ask for more instead of stopping: the
    /// Flow and the radios (`lib/flow.js`, `lib/queryradio.js`). A playlist, an
    /// album or a show ends where it ends.
    pub fn wants_more(&self) -> bool {
        matches!(self.kind.as_str(), "flow" | "radio")
    }
}

/// The args of a command that carries none, on the wire as `"args": {}`.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct NoArgs {}

/// `{"t": seconds}`.
#[derive(Debug, Clone, Copy, Default, PartialEq, Serialize, Deserialize)]
pub struct SeekArgs {
    #[serde(default)]
    pub t: f64,
}

/// `{"i": index, "id": row}` — a row named by its index AND its id, because the
/// queue may have moved between the controller reading it and the command
/// landing (`commands.js#resolveIndex`).
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct IndexArgs {
    #[serde(default)]
    pub i: i64,
    /// Absent only for a command this device made itself, where the index is
    /// the whole truth.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub id: Option<String>,
}

/// `{"i", "id", "to"}`.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct MoveArgs {
    #[serde(default)]
    pub i: i64,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub id: Option<String>,
    #[serde(default)]
    pub to: i64,
}

/// `{"v": 0..1}`.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
pub struct VolumeArgs {
    #[serde(default = "full_volume")]
    pub v: f64,
}

fn full_volume() -> f64 {
    1.0
}

impl Default for VolumeArgs {
    fn default() -> Self {
        Self { v: 1.0 }
    }
}

/// `{"tracks": [...]}`, for what is added to a queue.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct TracksArgs {
    #[serde(default)]
    pub tracks: Vec<Entry>,
}

/// `{"tracks", "context"}`, for a queue that starts shuffled.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct ShuffleArgs {
    #[serde(default)]
    pub tracks: Vec<Entry>,
    /// Always present on the wire, `null` when there is none.
    #[serde(default)]
    pub context: Option<Context>,
}

/// `{"tracks", "start", "context"}`, for what replaces the queue.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct QueueArgs {
    #[serde(default)]
    pub tracks: Vec<Entry>,
    #[serde(default)]
    pub start: usize,
    /// Always present on the wire, `null` when there is none.
    #[serde(default)]
    pub context: Option<Context>,
}

/// One thing to do to the player.
///
/// The Rust names are the player-store methods (`playQueue`, `removeAt`,
/// `toggleShuffle`…), the serde tags are the wire ops, and [`Command::op`]
/// gives the op back for a log line or a permission check.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "op", rename_all = "snake_case")]
pub enum Command {
    /// `player.play()`.
    Play {
        #[serde(default)]
        args: NoArgs,
    },
    /// `player.pause()`.
    Pause {
        #[serde(default)]
        args: NoArgs,
    },
    /// `player.toggle()`.
    Toggle {
        #[serde(default)]
        args: NoArgs,
    },
    /// `player.next()`.
    Next {
        #[serde(default)]
        args: NoArgs,
    },
    /// `player.prev()`.
    Prev {
        #[serde(default)]
        args: NoArgs,
    },
    /// A position asked for by the operator (a remote drag): the state machine
    /// answers with a `Load` at that offset, so the engine's own seek path is
    /// the one that runs.
    Seek {
        #[serde(default)]
        args: SeekArgs,
    },
    /// `player.jump(i)`.
    Jump {
        #[serde(default)]
        args: IndexArgs,
    },
    /// `player.removeAt(i)`.
    #[serde(rename = "remove")]
    RemoveAt {
        #[serde(default)]
        args: IndexArgs,
    },
    /// `player.move(from, to)`.
    Move {
        #[serde(default)]
        args: MoveArgs,
    },
    /// `player.clearUpcoming()`.
    #[serde(rename = "clear")]
    ClearUpcoming {
        #[serde(default)]
        args: NoArgs,
    },
    /// `player.setVolume(v)`.
    #[serde(rename = "volume")]
    SetVolume {
        #[serde(default)]
        args: VolumeArgs,
    },
    /// `player.toggleMute()`.
    #[serde(rename = "mute")]
    ToggleMute {
        #[serde(default)]
        args: NoArgs,
    },
    /// `player.toggleShuffle()`.
    #[serde(rename = "shuffle")]
    ToggleShuffle {
        #[serde(default)]
        args: NoArgs,
    },
    /// `player.cycleRepeat()`.
    #[serde(rename = "repeat")]
    CycleRepeat {
        #[serde(default)]
        args: NoArgs,
    },
    /// `player.addToQueue(tracks)`.
    #[serde(rename = "add")]
    AddToQueue {
        #[serde(default)]
        args: TracksArgs,
    },
    /// `player.playNext(tracks)`.
    #[serde(rename = "play_next")]
    PlayNext {
        #[serde(default)]
        args: TracksArgs,
    },
    /// `player.playQueue(tracks, start, context)`.
    #[serde(rename = "play_queue")]
    PlayQueue {
        #[serde(default)]
        args: QueueArgs,
    },
    /// `player.shufflePlay(tracks, context)`.
    #[serde(rename = "shuffle_play")]
    ShufflePlay {
        #[serde(default)]
        args: ShuffleArgs,
    },
}

impl Command {
    pub fn play() -> Self {
        Self::Play { args: NoArgs {} }
    }

    pub fn pause() -> Self {
        Self::Pause { args: NoArgs {} }
    }

    pub fn toggle() -> Self {
        Self::Toggle { args: NoArgs {} }
    }

    pub fn next() -> Self {
        Self::Next { args: NoArgs {} }
    }

    pub fn prev() -> Self {
        Self::Prev { args: NoArgs {} }
    }

    pub fn clear_upcoming() -> Self {
        Self::ClearUpcoming { args: NoArgs {} }
    }

    pub fn toggle_mute() -> Self {
        Self::ToggleMute { args: NoArgs {} }
    }

    pub fn toggle_shuffle() -> Self {
        Self::ToggleShuffle { args: NoArgs {} }
    }

    pub fn cycle_repeat() -> Self {
        Self::CycleRepeat { args: NoArgs {} }
    }

    /// A seek this device made. A remote one comes from the wire with its id.
    pub fn seek(t: f64) -> Self {
        Self::Seek {
            args: SeekArgs { t },
        }
    }

    pub fn jump(i: usize) -> Self {
        Self::Jump {
            args: IndexArgs {
                i: i as i64,
                id: None,
            },
        }
    }

    pub fn jump_named(i: usize, id: impl Into<String>) -> Self {
        Self::Jump {
            args: IndexArgs {
                i: i as i64,
                id: Some(id.into()),
            },
        }
    }

    pub fn remove_at(i: usize) -> Self {
        Self::RemoveAt {
            args: IndexArgs {
                i: i as i64,
                id: None,
            },
        }
    }

    pub fn remove_named(i: usize, id: impl Into<String>) -> Self {
        Self::RemoveAt {
            args: IndexArgs {
                i: i as i64,
                id: Some(id.into()),
            },
        }
    }

    pub fn move_to(from: usize, to: usize) -> Self {
        Self::Move {
            args: MoveArgs {
                i: from as i64,
                id: None,
                to: to as i64,
            },
        }
    }

    pub fn set_volume(v: f64) -> Self {
        Self::SetVolume {
            args: VolumeArgs { v },
        }
    }

    pub fn add_to_queue(tracks: Vec<Entry>) -> Self {
        Self::AddToQueue {
            args: TracksArgs { tracks },
        }
    }

    pub fn play_next(tracks: Vec<Entry>) -> Self {
        Self::PlayNext {
            args: TracksArgs { tracks },
        }
    }

    pub fn play_queue(tracks: Vec<Entry>, start: usize, context: Option<Context>) -> Self {
        Self::PlayQueue {
            args: QueueArgs {
                tracks,
                start,
                context,
            },
        }
    }

    pub fn shuffle_play(tracks: Vec<Entry>, context: Option<Context>) -> Self {
        Self::ShufflePlay {
            args: ShuffleArgs { tracks, context },
        }
    }

    /// The op the wire (and the server's `remote.py#OPS`) names this command.
    pub fn op(&self) -> &'static str {
        match self {
            Self::Play { .. } => "play",
            Self::Pause { .. } => "pause",
            Self::Toggle { .. } => "toggle",
            Self::Next { .. } => "next",
            Self::Prev { .. } => "prev",
            Self::Seek { .. } => "seek",
            Self::Jump { .. } => "jump",
            Self::RemoveAt { .. } => "remove",
            Self::Move { .. } => "move",
            Self::ClearUpcoming { .. } => "clear",
            Self::SetVolume { .. } => "volume",
            Self::ToggleMute { .. } => "mute",
            Self::ToggleShuffle { .. } => "shuffle",
            Self::CycleRepeat { .. } => "repeat",
            Self::AddToQueue { .. } => "add",
            Self::PlayNext { .. } => "play_next",
            Self::PlayQueue { .. } => "play_queue",
            Self::ShufflePlay { .. } => "shuffle_play",
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn entry(id: &str) -> Entry {
        Entry::new(id)
    }

    #[test]
    fn a_command_is_tagged_with_its_op_and_an_args_object() {
        let json = serde_json::to_value(Command::next()).unwrap();
        assert_eq!(json, serde_json::json!({"op": "next", "args": {}}));
        // The compact form a hand-written client may send also parses.
        let parsed: Command = serde_json::from_str(r#"{"op":"next"}"#).unwrap();
        assert_eq!(parsed, Command::next());
    }

    #[test]
    fn the_store_names_and_the_wire_names_are_one_table() {
        // Rust name (the store method) on the left, wire op on the right: the
        // server's OPS table and commands.js must agree with it.
        let cases = [
            (Command::play(), "play"),
            (Command::pause(), "pause"),
            (Command::toggle(), "toggle"),
            (Command::next(), "next"),
            (Command::prev(), "prev"),
            (Command::seek(1.0), "seek"),
            (Command::jump(0), "jump"),
            (Command::remove_at(0), "remove"),
            (Command::move_to(0, 1), "move"),
            (Command::clear_upcoming(), "clear"),
            (Command::set_volume(0.5), "volume"),
            (Command::toggle_mute(), "mute"),
            (Command::toggle_shuffle(), "shuffle"),
            (Command::cycle_repeat(), "repeat"),
            (Command::add_to_queue(vec![]), "add"),
            (Command::play_next(vec![]), "play_next"),
            (Command::play_queue(vec![], 0, None), "play_queue"),
            (Command::shuffle_play(vec![], None), "shuffle_play"),
        ];
        for (cmd, op) in cases {
            assert_eq!(cmd.op(), op);
            let json = serde_json::to_value(&cmd).unwrap();
            assert_eq!(json["op"], op, "{json}");
        }
    }

    #[test]
    fn a_local_index_command_carries_no_id_and_a_remote_one_does() {
        let local = serde_json::to_value(Command::jump(2)).unwrap();
        assert_eq!(local, serde_json::json!({"op": "jump", "args": {"i": 2}}));
        let remote: Command =
            serde_json::from_str(&serde_json::to_string(&Command::jump_named(2, "row")).unwrap())
                .unwrap();
        assert_eq!(remote, Command::jump_named(2, "row"));
    }

    #[test]
    fn only_the_flow_and_the_radios_ask_for_more() {
        assert!(Context::new("flow").wants_more());
        assert!(Context::new("radio").wants_more());
        assert!(!Context::new("album").wants_more());
        assert!(!Context::new("playlist").wants_more());
        assert!(!Context::default().wants_more());
    }

    #[test]
    fn a_queue_command_keeps_a_null_context_on_the_wire() {
        let cmd = Command::play_queue(vec![entry("a")], 0, None);
        let json = serde_json::to_value(&cmd).unwrap();
        assert_eq!(json["args"]["context"], serde_json::Value::Null);
        let back: Command = serde_json::from_value(json).unwrap();
        assert_eq!(back, cmd);
    }
}
